  assert.deepEqual(fresh.toFix, []);
  const scope = decideRound({ files: FILES, root: ROOT, touched: [HELPER], found: [f('F1', { path: HELPER, category: 'scope' }), f('F2', { path: HELPER })], resolution: { accept: ['F1'] } });
